import { tags } from "typia";

/**
 * Dashboard summary containing aggregated shop performance metrics for the authenticated seller.
 *
 * All values are non-negative integer counts computed in real-time from the seller's current data. If the seller has no products or no orders, all metrics return zero rather than null.
 *
 * The seller is identified through their authenticated session token — no explicit identifier is required.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IECommerceMallSellerDashboard = {
  /**
   * Total number of active (non-deleted) products belonging to this seller.
   *
   * This count reflects only products that the seller has created and not subsequently deleted. Soft-deleted products are excluded from this tally. If the seller has no products, this value is zero.
   *
     * @x-autobe-specification SELECT COUNT(*) FROM e_commerce_mall_products
     *   WHERE seller_id = {sellerId} AND deleted_at IS NULL. Returns 0 if the
     *   seller has no products.
   */
  totalProducts: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Total number of order items received across all of this seller's products.
   *
   * This metric aggregates every line item from customer orders that reference any variant of any product owned by the seller. It includes all order items regardless of their current status (paid, shipped, delivered, cancelled, or refunded). If no orders have been placed for the seller's products, this value is zero.
   *
     * @x-autobe-specification SELECT COUNT(*) FROM e_commerce_mall_order_items
     *   oi JOIN e_commerce_mall_product_variants pv ON
     *   oi.e_commerce_mall_product_variant_id = pv.id JOIN
     *   e_commerce_mall_products p ON pv.e_commerce_mall_product_id = p.id
     *   WHERE p.seller_id = {sellerId}. Returns 0 if no orders exist for any of
     *   the seller's products.
   */
  totalOrderItems: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of cancellation requests with status 'pending' that require this seller's attention.
   *
   * These are customer-initiated requests to cancel a paid order item before it has been shipped. Each pending request awaits the seller's decision to either approve or reject. If there are no pending cancellation requests for this seller's products, this value is zero.
   *
     * @x-autobe-specification SELECT COUNT(*) FROM
     *   e_commerce_mall_cancellation_requests cr JOIN
     *   e_commerce_mall_order_items oi ON cr.e_commerce_mall_order_item_id =
     *   oi.id JOIN e_commerce_mall_product_variants pv ON
     *   oi.e_commerce_mall_product_variant_id = pv.id JOIN
     *   e_commerce_mall_products p ON pv.e_commerce_mall_product_id = p.id
     *   WHERE p.seller_id = {sellerId} AND cr.status = 'pending'. Returns 0 if
     *   no pending cancellation requests exist.
   */
  pendingCancellationRequests: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of refund requests with status 'pending' that require this seller's attention.
   *
   * These are customer-initiated requests to obtain a refund for a specific delivered order item within the 7-day refund window. Each pending request awaits the seller's decision to either approve or reject. If there are no pending refund requests for this seller's products, this value is zero.
   *
     * @x-autobe-specification SELECT COUNT(*) FROM
     *   e_commerce_mall_refund_requests rr JOIN e_commerce_mall_order_items oi
     *   ON rr.e_commerce_mall_order_item_id = oi.id JOIN
     *   e_commerce_mall_product_variants pv ON
     *   oi.e_commerce_mall_product_variant_id = pv.id JOIN
     *   e_commerce_mall_products p ON pv.e_commerce_mall_product_id = p.id
     *   WHERE p.seller_id = {sellerId} AND rr.status = 'pending'. Returns 0 if
     *   no pending refund requests exist.
   */
  pendingRefundRequests: number & tags.Type<"int32"> & tags.Minimum<0>;
};
